    def write_number(self, number):
        if self.label.text() == "0" or self.is_equal:
            self.label.setText(number)
            self.is_equal = False
        else:
            self.label.setText(self.label.text() + number)

    def results(self):
        if not self.is_equal:
            res = eval(self.label.text())
            self.label.setText("Result : " + str(res))
            self.is_equal = True
        else:
            error = QMessageBox()
            error.setWindowTitle("Error")
            error.setText("It's impossible to calculate this number")
            error.setIcon(QMessageBox.Warning)
            error.setStandardButtons(QMessageBox.Reset|QMessageBox.Ok|QMessageBox.Cancel)

            error.setDefaultButton(QMessageBox.Ok)
            error.setInformativeText("It's impossible to calculate this number. Try again later.")
            error.setDetailedText("Try again later. Try again later. Try again later. Try again later.")

            error.buttonClicked.connect(self.popup_action)

            error.exec_()

    def popup_action(self, btn):
        if btn.text() == "OK":
            print("Ok")
        elif btn.text() == "Reset":
            self.label.setText("0")
            self.is_equal = False



